/**
 * Creates a deterministic mock ImageData object
 */
export function createMockImageData(
  width = 2,
  height = 2,
  fillColor: [number, number, number, number] = [255, 0, 0, 255],
): ImageData {
  const pixelCount = width * height;
  const data = new Uint8ClampedArray(pixelCount * 4);
  for (let i = 0; i < pixelCount; i++) {
    data[i * 4] = fillColor[0];
    data[i * 4 + 1] = fillColor[1];
    data[i * 4 + 2] = fillColor[2];
    data[i * 4 + 3] = fillColor[3];
  }

  return {
    width,
    height,
    data,
    colorSpace: 'srgb',
  } as ImageData;
}

/**
 * Creates a deterministic Mock CanvasRenderingContext2D for headless tests
 */
export function createMockCanvasContext(options?: {
  charWidth?: number;
}): CanvasRenderingContext2D {
  const charWidth = options?.charWidth ?? 10;

  const mockCtx = {
    font: '16px Inter',
    fillStyle: '#ffffff',
    strokeStyle: '#000000',
    lineWidth: 1,
    textAlign: 'left',
    textBaseline: 'top',
    filter: 'none',
    measureText: (text: string) => ({
      width: text.length * charWidth,
      actualBoundingBoxAscent: 12,
      actualBoundingBoxDescent: 4,
    }),
    fillText: () => {},
    strokeText: () => {},
    fillRect: () => {},
    strokeRect: () => {},
    clearRect: () => {},
    drawImage: () => {},
    getImageData: (_sx: number, _sy: number, sw: number, sh: number) =>
      createMockImageData(sw, sh),
    putImageData: () => {},
    save: () => {},
    restore: () => {},
    beginPath: () => {},
    closePath: () => {},
    moveTo: () => {},
    lineTo: () => {},
    arc: () => {},
    fill: () => {},
    stroke: () => {},
  };

  return mockCtx as unknown as CanvasRenderingContext2D;
}
